      cin>>table[i][j];
  int index = 0;
  for(int i=1;i<=6;i++)
    for(int j=i+1;j<=6;j++)
      for(int k=j+1;k<=6;k++)
        maska[(1<<i) ^ (1<<j) ^ (1<<k)] = (1<<index++);
  for(int i=7;i<=6;i++) table[i][i]=100;
  vector<PII> edges;
  n=6;
  for(int i=1;i<=n;i++)
    for(int j=1;j<=n;j++)
      edges.push_back({i,j});
  LL inv_100 = power(100, MOD-2);
  for(int k=0;k<2;k++)
    for(int i=0;i<(1<<18);i++)
    {
      LL prob=1LL;
      for(int j=0;j<18;j++)
      {
        if((1<<j)&i)
        {
          prob = prob * table[edges[j + k*18].first][edges[j + k*18].second] % MOD * inv_100 % MOD;
          elo[edges[j + k*18].second][edges[j + k*18].first]=1;
        }
        else
        {
          prob = prob * (100 - table[edges[j + k*18].first][edges[j + k*18].second]) % MOD * inv_100 % MOD;
          elo[edges[j + k*18].second][edges[j + k*18].first]=0;
        }
      }
      int current_mask=compute_mask(k);
      dp[current_mask][k] += prob;
      dp[current_mask][k] %= MOD;
    }
  LL answer=1;
  for(int i=0;i<20;i++)
    for(int j=0;j<(1<<20);j++)
      if((1<<i)&j)
      {
        dp[j][0] += dp[j^(1<<i)][0];
        dp[j][0] %= MOD;
      }
  for(int i=0;i<(1<<20);i++)
  {
    answer = (answer - dp[i][0]*dp[((1<<20)-1)^i][1])%MOD;
  }
  answer = (answer + MOD)%MOD;
  cout<<answer;
  return 0;
}
